using System;using System.IO;using System.Threading.Tasks;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using CodexStrip;
class PanelSizeComparison {
 const string Dir="outputs/ScreenSimulation/";
 static void Save(BitmapSource b,string name){var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Dir+name))e.Save(f);}
 static void Label(DrawingContext dc,string text,double x,double y,double size,Brush brush){dc.DrawText(new FormattedText(text,System.Globalization.CultureInfo.GetCultureInfo("zh-CN"),FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),size,brush),new Point(x,y));}
 [STAThread]static void Main(){Directory.CreateDirectory(Dir);Settings.DataDir=Path.GetFullPath("work/panel-comparison-data");var app=new Application();var w=new StripWindow(true){Width=1280,Height=320,Left=0,Top=0};w.Config.Count=4;w.Config.Host="all";w.Loaded+=async delegate{try{w.SetTheme("light");var images=new BitmapSource[2];int[] heights={480,440};double[] diagonals={8.8,11.3};for(int i=0;i<2;i++){w.Width=1280;w.Height=heights[i]/1.5;await Task.Delay(350);w.UpdateLayout();var b=new RenderTargetBitmap(1920,heights[i],144,144,PixelFormats.Pbgra32);b.Render(w);images[i]=b;Save(b,i==0?"8.8-inch-150.png":"11.3-inch-150.png");}
 var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new Rect(0,0,1200,820));Label(dc,"8.8 寸 vs 11.3 寸 · 真实显示面积比例",40,20,28,Brushes.Black);Label(dc,"均为 150% 缩放 / 四个线程 / 演示数据 / 看板占满副屏",40,65,18,Brushes.DimGray);for(int i=0;i<2;i++){double y=i==0?120:430;double cmW=diagonals[i]*2.54*1920/Math.Sqrt(1920.0*1920+heights[i]*heights[i]);double cmH=cmW*heights[i]/1920;Label(dc,diagonals[i]+" 寸 · 1920 × "+heights[i]+" · 显示区约 "+cmW.ToString("0.0")+" × "+cmH.ToString("0.0")+" cm",40,y,22,Brushes.Black);var rect=new Rect(40,y+42,cmW*40,cmH*40);dc.DrawImage(images[i],rect);dc.DrawRectangle(null,new Pen(Brushes.LightGray,1),rect);}Label(dc,"两张图使用同一物理比例；聊天中的显示大小不等于实物。外壳与支架未计入。",40,754,18,Brushes.DimGray);Label(dc,"11.3 寸：字约大 29%，实际屏高约多 18%；像素高度少 40，内容空间略少。",40,786,18,Brushes.DimGray);}var sheet=new RenderTargetBitmap(1200,820,96,96,PixelFormats.Pbgra32);sheet.Render(visual);Save(sheet,"8.8-vs-11.3.png");File.WriteAllText("work/panel-comparison.txt","PASS: native UI rendered at 1280x320 and 1280x293.33 logical pixels; output 1920x480 and 1920x440; composition uses diagonal-derived physical dimensions");}catch(Exception e){File.WriteAllText("work/panel-comparison.txt",e.ToString());}finally{w.Close();}};app.Run(w);}
}
